const since = new Date();
since.setDate(since.getDate() - 30);

const items = $input.first().json.items || [];
const recentIds = items
  .filter((it) => new Date(it.contentDetails.videoPublishedAt) >= since)
  .map((it) => it.contentDetails.videoId);

return [{ json: { videoIds: recentIds.join(',') } }];

const channel = $('GET channels (statistics,status,contentDetails)').item.json.items[0];
const videos = ($json.items) || [];

const views = videos.map((v) => parseInt(v.statistics.viewCount || '0', 10));
const totalViews = views.reduce((sum, v) => sum + v, 0);

return [{
  json: {
    platform: 'youtube',
    account_id: channel.id,
    account_name: channel.snippet.title,
    followers_count: channel.statistics.hiddenSubscriberCount ? null : parseInt(channel.statistics.subscriberCount, 10),
    views_recent_30d: videos.length ? totalViews : null,
    views_average: videos.length ? Math.round(totalViews / videos.length) : null,
    account_status: channel.status.privacyStatus || null
  }
}];
